const ALLOWED_CHAT_ID = -1004453819959; // seul le groupe BDE peut piloter le bot
const SIGNATURE = "<p>Cordialement,</p><p>L'équipe Partenariats - Liste BDE ESSEC</p>";
const USAGE = [
  "❓ Commande non reconnue. Commandes disponibles :",
  "• GO #id : rédiger le mail du prospect",
  "• OK #id : envoyer le mail validé",
  "• EDIT #id votre texte : remplacer le brouillon",
  "Exemple : GO #12"
].join("\n");

const item = $input.first().json;
const msg = item.message || {};
const text = (msg.text || '').trim();
const chat_id = msg.chat && msg.chat.id ? Number(msg.chat.id) : null;

let action = 'ignore';
let contact_id = null;
let new_text = null;
let new_html = null;
let usage_message = null;

if (chat_id === ALLOWED_CHAT_ID) {
  const goMatch = text.match(/^GO\s+#(\d+)\s*$/i);
  const okMatch = text.match(/^OK\s+#(\d+)\s*$/i);
  const editMatch = text.match(/^EDIT\s+#(\d+)\s+([\s\S]+)$/i);
  // Ressemble à une commande mais mal formée (ex. "GO 1", "OK #abc", "EDIT #3" sans texte, "/aide")
  const looksLikeCommand = /^(GO|OK|EDIT)(\s|#|$)/i.test(text) || text.startsWith('/');

  if (goMatch) {
    action = 'go';
    contact_id = parseInt(goMatch[1], 10);
  } else if (okMatch) {
    action = 'ok';
    contact_id = parseInt(okMatch[1], 10);
  } else if (editMatch) {
    action = 'edit';
    contact_id = parseInt(editMatch[1], 10);
    new_text = editMatch[2].trim();
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    new_html = new_text
      .split(/\n\s*\n/)
      .map(p => '<p>' + esc(p.trim()).replace(/\n/g, '<br>') + '</p>')
      .join('');
    if (!/Partenariats - Liste BDE ESSEC/i.test(new_text)) new_html += SIGNATURE;
  } else if (looksLikeCommand) {
    action = 'usage';
    usage_message = USAGE;
  }
}

return [{ json: { action, contact_id, new_text, new_html, usage_message, chat_id, raw_text: text } }];

// Remplace TOUT le code du nœud "C3 - Code Préparer Relance"
const items = $input.all();
const out = [];

for (const it of items) {
  const c = it.json;

  const preambule =
    `<p>Bonjour ${c.nom},</p>` +
    `<p>Je me permets de revenir vers vous au sujet de mon précédent message concernant ${c.produit_interesse}, que je vous remets ci-dessous.</p>` +
    `<hr>`;

  // Retire la formule d'appel du mail d'origine pour éviter un double "Bonjour"
  const corps = (c.mail_genere || '')
    .replace(/^\s*<p>\s*(Bonjour|Madame|Monsieur|Cher|Chère)[^<]*<\/p>/i, '');

  out.push({
    json: {
      id: c.id,
      email: c.email,
      nom: c.nom,
      entreprise: c.entreprise,
      produit_interesse: c.produit_interesse,
      nombre_relances: c.nombre_relances,
      mail_relance: preambule + corps,
      sujet_relance: '[Relance] ' + (c.mail_sujet || '')
    }
  });
}

return out;

const items = $input.all();
const out = [];

const autoReplyKeywords = [
  'out of office', 'absence', 'absent', 'congés', 'congé',
  'réponse automatique', 'reponse automatique', 'auto-reply', 'auto reply', 'automatic reply',
  'noreply', 'no-reply', 'no_reply',
  'mailer-daemon', 'mailer daemon', 'postmaster',
  'undeliverable', 'undelivered', 'delivery status notification', 'delivery failure',
  'message rejected', 'returned mail'
];

// Normalise n'importe quel champ (string, objet {text}, objet {value:[{address}]}) en string
function toStr(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    if (v.text) return v.text;
    if (Array.isArray(v.value) && v.value.length) {
      return v.value.map(x => `${x.name || ''} <${x.address || ''}>`).join(', ');
    }
    if (v.address) return `${v.name || ''} <${v.address}>`;
  }
  return String(v);
}

function extractEmail(from) {
  if (!from) return null;
  const m = from.match(/[\w\.\-+]+@[\w\.\-]+\.[A-Za-z]{2,}/);
  return m ? m[0].toLowerCase() : null;
}

function cleanBody(raw) {
  if (!raw) return '';
  let txt = raw.replace(/<[^>]+>/g, ' ');
  txt = txt.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
  const cutPatterns = [
    /\nLe\s+.+?a\s+écrit\s*:/i,
    /\nOn\s+.+?wrote\s*:/i,
    /\nDe\s*:\s*.+\nEnvoyé/i,
    /\nFrom\s*:\s*.+\nSent/i
  ];
  for (const p of cutPatterns) {
    const idx = txt.search(p);
    if (idx >= 0) { txt = txt.substring(0, idx); }
  }
  txt = txt.split('\n').filter(l => !l.trim().startsWith('>')).join('\n');
  return txt.trim().replace(/\s+\n/g, '\n').replace(/\n{3,}/g, '\n\n');
}

for (const it of items) {
  const msg = it.json;
  const headers = msg.payload && msg.payload.headers ? msg.payload.headers : [];
  const getHeader = (n) => {
    const h = headers.find(x => x.name && x.name.toLowerCase() === n.toLowerCase());
    return h ? h.value : '';
  };

  const subject = toStr(msg.subject) || getHeader('Subject') || '';
  const from = toStr(msg.from) || getHeader('From') || '';
  const thread_id = msg.threadId || '';
  const message_id = msg.id || getHeader('Message-ID') || '';
  const bodyRaw = toStr(msg.text) || msg.snippet || toStr(msg.textPlain) || '';

  const lowFrom = from.toLowerCase();
  const lowSubject = subject.toLowerCase();
  // Détection auto-reply uniquement sur from + subject (pas le corps cité)
  const isAuto = autoReplyKeywords.some(k => lowFrom.includes(k) || lowSubject.includes(k));
  if (isAuto) continue;

  const prospect_email = extractEmail(from);
  if (!prospect_email) continue;

  // On ignore nos propres mails
  if (prospect_email.endsWith('@essec-liste-bde.com')) continue;

  const body = cleanBody(bodyRaw.toString());

  out.push({
    json: { prospect_email, subject, body, from_header: from, thread_id, message_id }
  });
}

return out;

